import pandas as pd
df = pd.read_csv('data.csv', parse_dates=['date'])
a = df[df.account_id=='xykrZYR']
rows=[]
for d in ['2025-10-19','2025-10-20']:
    sub=a[a.date==d]
    for c in ['csp','cloud_service','application','instance_family']:
        b=sub.groupby(c).unblended_cost.sum()
        rows.append((d,c,len(b),b.idxmax(),round(b.max(),2)))
for r in rows: print(r)

